use split_decls_genesis :: ourprelude :: * ; use crate :: io :: { self , DEFAULT_BUF_SIZE , ErrorKind , IntoInnerError , IoSlice , Seek , SeekFrom , Write , } ; use crate :: mem :: { self , ManuallyDrop } ; use crate :: { error , fmt , ptr } ; #[doc = " Wraps a writer and buffers its output."] #[doc = ""] #[doc = " It can be excessively inefficient to work directly with something that"] #[doc = " implements [`Write`]. For example, every call to"] #[doc = " [`write`][`TcpStream::write`] on [`TcpStream`] results in a system call. A"] #[doc = " `BufWriter<W>` keeps an in-memory buffer of data and writes it to an underlying"] #[doc = " writer in large, infrequent batches."] #[doc = ""] #[doc = " `BufWriter<W>` can improve the speed of programs that make *small* and"] #[doc = " *repeated* write calls to the same file or network socket. It does not"] #[doc = " help when writing very large amounts at once, or writing just one or a few"] #[doc = " times. It also provides no advantage when writing to a destination that is"] #[doc = " in memory, like a <code>[Vec]\\<u8></code>."] #[doc = ""] #[doc = " It is critical to call [`flush`] before `BufWriter<W>` is dropped. Though"] #[doc = " dropping will attempt to flush the contents of the buffer, any errors"] #[doc = " that happen in the process of dropping will be ignored. Calling [`flush`]"] #[doc = " ensures that the buffer is empty and thus dropping will not even attempt"] #[doc = " file operations."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Let's write the numbers one through ten to a [`TcpStream`]:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::prelude::*;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut stream = TcpStream::connect(\"127.0.0.1:34254\").unwrap();"] #[doc = ""] #[doc = " for i in 0..10 {"] #[doc = "     stream.write(&[i+1]).unwrap();"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Because we're not buffering, we write each one in turn, incurring the"] #[doc = " overhead of a system call per byte written. We can fix this with a"] #[doc = " `BufWriter<W>`:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::prelude::*;"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut stream = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " for i in 0..10 {"] #[doc = "     stream.write(&[i+1]).unwrap();"] #[doc = " }"] #[doc = " stream.flush().unwrap();"] #[doc = " ```"] #[doc = ""] #[doc = " By wrapping the stream with a `BufWriter<W>`, these ten writes are all grouped"] #[doc = " together by the buffer and will all be written out in one system call when"] #[doc = " the `stream` is flushed."] #[doc = ""] #[doc = " [`TcpStream::write`]: crate::net::TcpStream::write"] #[doc = " [`TcpStream`]: crate::net::TcpStream"] #[doc = " [`flush`]: BufWriter::flush"] #[stable (feature = "rust1" , since = "1.0.0")] pub struct BufWriter < W : ? Sized + Write > { buf : Vec < u8 > , panicked : bool , inner : W , } impl < W : Write > BufWriter < W > { #[doc = " Creates a new `BufWriter<W>` with a default buffer capacity. The default is currently 8 KiB,"] #[doc = " but may change in the future."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut buffer = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn new (inner : W) -> BufWriter < W > { BufWriter :: with_capacity (DEFAULT_BUF_SIZE , inner) } pub (crate) fn try_new_buffer () -> io :: Result < Vec < u8 > > { Vec :: try_with_capacity (DEFAULT_BUF_SIZE) . map_err (| _ | { io :: const_error ! (ErrorKind :: OutOfMemory , "failed to allocate write buffer") }) } pub (crate) fn with_buffer (inner : W , buf : Vec < u8 >) -> Self { Self { inner , buf , panicked : false } } #[doc = " Creates a new `BufWriter<W>` with at least the specified buffer capacity."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Creating a buffer with a buffer of at least a hundred bytes."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let stream = TcpStream::connect(\"127.0.0.1:34254\").unwrap();"] #[doc = " let mut buffer = BufWriter::with_capacity(100, stream);"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn with_capacity (capacity : usize , inner : W) -> BufWriter < W > { BufWriter { inner , buf : Vec :: with_capacity (capacity) , panicked : false } } #[doc = " Unwraps this `BufWriter<W>`, returning the underlying writer."] #[doc = ""] #[doc = " The buffer is written out before returning the writer."] #[doc = ""] #[doc = " # Errors"] #[doc = ""] #[doc = " An [`Err`] will be returned if an error occurs while flushing the buffer."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut buffer = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // unwrap the TcpStream and flush the buffer"] #[doc = " let stream = buffer.into_inner().unwrap();"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn into_inner (mut self) -> Result < W , IntoInnerError < BufWriter < W > > > { match self . flush_buf () { Err (e) => Err (IntoInnerError :: new (self , e)) , Ok (()) => Ok (self . into_parts () . 0) , } } #[doc = " Disassembles this `BufWriter<W>`, returning the underlying writer, and any buffered but"] #[doc = " unwritten data."] #[doc = ""] #[doc = " If the underlying writer panicked, it is not known what portion of the data was written."] #[doc = " In this case, we return `WriterPanicked` for the buffered data (from which the buffer"] #[doc = " contents can still be recovered)."] #[doc = ""] #[doc = " `into_parts` makes no attempt to flush data and cannot fail."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::io::{BufWriter, Write};"] #[doc = ""] #[doc = " let mut buffer = [0u8; 10];"] #[doc = " let mut stream = BufWriter::new(buffer.as_mut());"] #[doc = " write!(stream, \"too much data\").unwrap();"] #[doc = " stream.flush().expect_err(\"it doesn't fit\");"] #[doc = " let (recovered_writer, buffered_data) = stream.into_parts();"] #[doc = " assert_eq!(recovered_writer.len(), 0);"] #[doc = " assert_eq!(&buffered_data.unwrap(), b\"ata\");"] #[doc = " ```"] #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] pub fn into_parts (self) -> (W , Result < Vec < u8 > , WriterPanicked >) { let mut this = ManuallyDrop :: new (self) ; let buf = mem :: take (& mut this . buf) ; let buf = if ! this . panicked { Ok (buf) } else { Err (WriterPanicked { buf }) } ; let inner = unsafe { ptr :: read (& this . inner) } ; (inner , buf) } } impl < W : ? Sized + Write > BufWriter < W > { #[doc = " Send data in our local buffer into the inner writer, looping as"] #[doc = " necessary until either it's all been sent or an error occurs."] #[doc = ""] #[doc = " Because all the data in the buffer has been reported to our owner as"] #[doc = " \"successfully written\" (by returning nonzero success values from"] #[doc = " `write`), any 0-length writes from `inner` must be reported as i/o"] #[doc = " errors from this method."] pub (in crate :: io) fn flush_buf (& mut self) -> io :: Result < () > { #[doc = " Helper struct to ensure the buffer is updated after all the writes"] #[doc = " are complete. It tracks the number of written bytes and drains them"] #[doc = " all from the front of the buffer when dropped."] struct BufGuard < 'a > { buffer : & 'a mut Vec < u8 > , written : usize , } impl < 'a > BufGuard < 'a > { fn new (buffer : & 'a mut Vec < u8 >) -> Self { Self { buffer , written : 0 } } #[doc = " The unwritten part of the buffer"] fn remaining (& self) -> & [u8] { & self . buffer [self . written ..] } #[doc = " Flag some bytes as removed from the front of the buffer"] fn consume (& mut self , amt : usize) { self . written += amt ; } #[doc = " true if all of the bytes have been written"] fn done (& self) -> bool { self . written >= self . buffer . len () } } impl Drop for BufGuard < '_ > { fn drop (& mut self) { if self . written > 0 { self . buffer . drain (.. self . written) ; } } } let mut guard = BufGuard :: new (& mut self . buf) ; while ! guard . done () { self . panicked = true ; let r = self . inner . write (guard . remaining ()) ; self . panicked = false ; match r { Ok (0) => { return Err (io :: const_error ! (ErrorKind :: WriteZero , "failed to write the buffered data" ,)) ; } Ok (n) => guard . consume (n) , Err (ref e) if e . is_interrupted () => { } Err (e) => return Err (e) , } } Ok (()) } #[doc = " Buffer some data without flushing it, regardless of the size of the"] #[doc = " data. Writes as much as possible without exceeding capacity. Returns"] #[doc = " the number of bytes written."] pub (super) fn write_to_buf (& mut self , buf : & [u8]) -> usize { let available = self . spare_capacity () ; let amt_to_buffer = available . min (buf . len ()) ; unsafe { self . write_to_buffer_unchecked (& buf [.. amt_to_buffer]) ; } amt_to_buffer } #[doc = " Gets a reference to the underlying writer."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut buffer = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // we can use reference just like buffer"] #[doc = " let reference = buffer.get_ref();"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn get_ref (& self) -> & W { & self . inner } #[doc = " Gets a mutable reference to the underlying writer."] #[doc = ""] #[doc = " It is inadvisable to directly write to the underlying writer."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut buffer = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // we can use reference just like buffer"] #[doc = " let reference = buffer.get_mut();"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn get_mut (& mut self) -> & mut W { & mut self . inner } #[doc = " Returns a reference to the internally buffered data."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let buf_writer = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // See how many bytes are currently buffered"] #[doc = " let bytes_buffered = buf_writer.buffer().len();"] #[doc = " ```"] #[stable (feature = "bufreader_buffer" , since = "1.37.0")] pub fn buffer (& self) -> & [u8] { & self . buf } #[doc = " Returns a mutable reference to the internal buffer."] #[doc = ""] #[doc = " This can be used to write data directly into the buffer without triggering writers"] #[doc = " to the underlying writer."] #[doc = ""] #[doc = " That the buffer is a `Vec` is an implementation detail."] #[doc = " Callers should not modify the capacity as there currently is no public API to do so"] #[doc = " and thus any capacity changes would be unexpected by the user."] pub (in crate :: io) fn buffer_mut (& mut self) -> & mut Vec < u8 > { & mut self . buf } #[doc = " Returns the number of bytes the internal buffer can hold without flushing."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let buf_writer = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // Check the capacity of the inner buffer"] #[doc = " let capacity = buf_writer.capacity();"] #[doc = " // Calculate how many bytes can be written without flushing"] #[doc = " let without_flush = capacity - buf_writer.buffer().len();"] #[doc = " ```"] #[stable (feature = "buffered_io_capacity" , since = "1.46.0")] pub fn capacity (& self) -> usize { self . buf . capacity () } #[cold] #[inline (never)] fn write_cold (& mut self , buf : & [u8]) -> io :: Result < usize > { if buf . len () > self . spare_capacity () { self . flush_buf () ? ; } if buf . len () >= self . buf . capacity () { self . panicked = true ; let r = self . get_mut () . write (buf) ; self . panicked = false ; r } else { unsafe { self . write_to_buffer_unchecked (buf) ; } Ok (buf . len ()) } } #[cold] #[inline (never)] fn write_all_cold (& mut self , buf : & [u8]) -> io :: Result < () > { if buf . len () > self . spare_capacity () { self . flush_buf () ? ; } if buf . len () >= self . buf . capacity () { self . panicked = true ; let r = self . get_mut () . write_all (buf) ; self . panicked = false ; r } else { unsafe { self . write_to_buffer_unchecked (buf) ; } Ok (()) } } #[inline] unsafe fn write_to_buffer_unchecked (& mut self , buf : & [u8]) { debug_assert ! (buf . len () <= self . spare_capacity ()) ; let old_len = self . buf . len () ; let buf_len = buf . len () ; let src = buf . as_ptr () ; unsafe { let dst = self . buf . as_mut_ptr () . add (old_len) ; ptr :: copy_nonoverlapping (src , dst , buf_len) ; self . buf . set_len (old_len + buf_len) ; } } #[inline] fn spare_capacity (& self) -> usize { self . buf . capacity () - self . buf . len () } } #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] #[doc = " Error returned for the buffered data from `BufWriter::into_parts`, when the underlying"] #[doc = " writer has previously panicked.  Contains the (possibly partly written) buffered data."] #[doc = ""] #[doc = " # Example"] #[doc = ""] #[doc = " ```"] #[doc = " use std::io::{self, BufWriter, Write};"] #[doc = " use std::panic::{catch_unwind, AssertUnwindSafe};"] #[doc = ""] #[doc = " struct PanickingWriter;"] #[doc = " impl Write for PanickingWriter {"] #[doc = "   fn write(&mut self, buf: &[u8]) -> io::Result<usize> { panic!() }"] #[doc = "   fn flush(&mut self) -> io::Result<()> { panic!() }"] #[doc = " }"] #[doc = ""] #[doc = " let mut stream = BufWriter::new(PanickingWriter);"] #[doc = " write!(stream, \"some data\").unwrap();"] #[doc = " let result = catch_unwind(AssertUnwindSafe(|| {"] #[doc = "     stream.flush().unwrap()"] #[doc = " }));"] #[doc = " assert!(result.is_err());"] #[doc = " let (recovered_writer, buffered_data) = stream.into_parts();"] #[doc = " assert!(matches!(recovered_writer, PanickingWriter));"] #[doc = " assert_eq!(buffered_data.unwrap_err().into_inner(), b\"some data\");"] #[doc = " ```"] pub struct WriterPanicked { buf : Vec < u8 > , } impl WriterPanicked { #[doc = " Returns the perhaps-unwritten data.  Some of this data may have been written by the"] #[doc = " panicking call(s) to the underlying writer, so simply writing it again is not a good idea."] #[must_use = "`self` will be dropped if the result is not used"] #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] pub fn into_inner (self) -> Vec < u8 > { self . buf } } #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] impl error :: Error for WriterPanicked { } #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] impl fmt :: Display for WriterPanicked { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { "BufWriter inner writer panicked, what data remains unwritten is not known" . fmt (f) } } #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] impl fmt :: Debug for WriterPanicked { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("WriterPanicked") . field ("buffer" , & format_args ! ("{}/{}" , self . buf . len () , self . buf . capacity ())) . finish () } } #[stable (feature = "rust1" , since = "1.0.0")] impl < W : ? Sized + Write > Write for BufWriter < W > { #[inline] fn write (& mut self , buf : & [u8]) -> io :: Result < usize > { if buf . len () < self . spare_capacity () { unsafe { self . write_to_buffer_unchecked (buf) ; } Ok (buf . len ()) } else { self . write_cold (buf) } } #[inline] fn write_all (& mut self , buf : & [u8]) -> io :: Result < () > { if buf . len () < self . spare_capacity () { unsafe { self . write_to_buffer_unchecked (buf) ; } Ok (()) } else { self . write_all_cold (buf) } } fn write_vectored (& mut self , bufs : & [IoSlice < '_ >]) -> io :: Result < usize > { if self . get_ref () . is_write_vectored () { let mut saturated_total_len : usize = 0 ; for buf in bufs { saturated_total_len = saturated_total_len . saturating_add (buf . len ()) ; if saturated_total_len > self . spare_capacity () && ! self . buf . is_empty () { self . flush_buf () ? ; } if saturated_total_len >= self . buf . capacity () { self . panicked = true ; let r = self . get_mut () . write_vectored (bufs) ; self . panicked = false ; return r ; } } unsafe { bufs . iter () . for_each (| b | self . write_to_buffer_unchecked (b)) ; } ; Ok (saturated_total_len) } else { let mut iter = bufs . iter () ; let mut total_written = if let Some (buf) = iter . by_ref () . find (| & buf | ! buf . is_empty ()) { if buf . len () > self . spare_capacity () { self . flush_buf () ? ; } if buf . len () >= self . buf . capacity () { self . panicked = true ; let r = self . get_mut () . write (buf) ; self . panicked = false ; return r ; } else { unsafe { self . write_to_buffer_unchecked (buf) ; } buf . len () } } else { return Ok (0) ; } ; debug_assert ! (total_written != 0) ; for buf in iter { if buf . len () <= self . spare_capacity () { unsafe { self . write_to_buffer_unchecked (buf) ; } total_written += buf . len () ; } else { break ; } } Ok (total_written) } } fn is_write_vectored (& self) -> bool { true } fn flush (& mut self) -> io :: Result < () > { self . flush_buf () . and_then (| () | self . get_mut () . flush ()) } } #[stable (feature = "rust1" , since = "1.0.0")] impl < W : ? Sized + Write > fmt :: Debug for BufWriter < W > where W : fmt :: Debug , { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { fmt . debug_struct ("BufWriter") . field ("writer" , & & self . inner) . field ("buffer" , & format_args ! ("{}/{}" , self . buf . len () , self . buf . capacity ())) . finish () } } #[stable (feature = "rust1" , since = "1.0.0")] impl < W : ? Sized + Write + Seek > Seek for BufWriter < W > { #[doc = " Seek to the offset, in bytes, in the underlying writer."] #[doc = ""] #[doc = " Seeking always writes out the internal buffer before seeking."] fn seek (& mut self , pos : SeekFrom) -> io :: Result < u64 > { self . flush_buf () ? ; self . get_mut () . seek (pos) } } #[stable (feature = "rust1" , since = "1.0.0")] impl < W : ? Sized + Write > Drop for BufWriter < W > { fn drop (& mut self) { if ! self . panicked { let _r = self . flush_buf () ; } } }